// Real backend evaluation (results/evaluation, regenerated by tools/export_landing_results.py).
const METRIC_COLUMNS = [
  { key: 'precision_at_3', label: 'PRECISION@3 ↑' },
  { key: 'ndcg_at_3', label: 'NDCG@3 ↑' },
  { key: 'type_hit_rate', label: 'TYPE HIT ↑' },
  { key: 'brier_score', label: 'BRIER ↓' },
  { key: 'mean_satisfaction', label: 'PRED. MEAN SAT ↑' },
  { key: 'min_satisfaction', label: 'PRED. MIN SAT ↑' },
  { key: 'satisfaction_gini', label: 'GINI ↓' },
];
const LOWER_IS_BETTER = new Set(['brier_score', 'satisfaction_gini']);
const rowById = Object.fromEntries(evaluationResults.rows.map((row) => [row.id, row]));
const formatValue = (value) => value.toFixed(3);

function verdictFor(metric) {
  const comparison = evaluationResults.mainVsBaseline[metric];
  if (comparison.better) return 'significantly better';
  const worse = LOWER_IS_BETTER.has(metric) ? comparison.low > 0 : comparison.high < 0;
  return worse ? 'significantly worse' : 'no significant difference';
}

const HEADLINE_PILLS = [
  { metric: 'precision_at_3', name: 'PRECISION@3 VS CLUB POPULARITY' },
  { metric: 'type_hit_rate', name: 'EVENT-TYPE HIT RATE' },
  { metric: 'brier_score', name: 'BRIER SCORE (LOWER IS BETTER)' },
  { metric: 'mean_satisfaction', name: 'PREDICTED MEAN SATISFACTION' },
  { metric: 'min_satisfaction', name: 'PREDICTED MIN SATISFACTION' },
].map((pill) => ({
  name: pill.name,
  val: `${formatValue(rowById.main_model.metrics[pill.metric].mean)} vs ${formatValue(rowById.club_popularity.metrics[pill.metric].mean)} · ${verdictFor(pill.metric)}`,
}));

const REPRODUCE_COMMAND = 'cd backend && python -m evaluation.runner --seeds 42 43 44 45 46 --output ../results/evaluation';

// Full-Width Jagged Vector Polyline Divider with 8x8 Black Vertex Handles (frame_058 - frame_062)
function JaggedVectorBoundary({ fillBelow = '#ABEBF7', fillAbove = '#FFFFFF' }) {
  const points = [
    { x: 0, y: 58 },
    { x: 268, y: 12 },
    { x: 625, y: 62 },
    { x: 1095, y: 20 },
    { x: 1472, y: 60 },
    { x: 1900, y: 8 },
  ];

  const polygonPoints = `0,75 ${points.map((p) => `${p.x},${p.y}`).join(' ')} 1900,75`;
  const polylinePoints = points.map((p) => `${p.x},${p.y}`).join(' ');

  return (
    <div style={{ width: '100%', backgroundColor: fillAbove, lineHeight: 0, overflow: 'hidden' }} aria-hidden="true">
      <svg width="100%" height="75" viewBox="0 0 1900 75" preserveAspectRatio="none" style={{ display: 'block' }}>
        <polygon points={polygonPoints} fill={fillBelow} />
        <polyline points={polylinePoints} fill="none" stroke="#111111" strokeWidth="2.5" />
        {points.map((pt, i) => (
          <rect
            key={i}
            x={pt.x - 5}
            y={pt.y - 5}
            width="10"
            height="10"
            fill="#111111"
          />
        ))}
      </svg>
    </div>
  );
}

